QUERIES = {'machine': 'SELECT d.gaming_date,d.machine_id,d.zone_name,d.bank_name,d.x_m,d.y_m,d.config_id,d.manufacturer,d.downtime_hours,d.zone_id,\n d.coin_in_usd,d.house_win_usd,d.theo_usd,d.leak_usd,d.location_opportunity_usd,\n d.luck_residual_usd,d.luck_variance_usd2,d.potential_theo_usd,d.location_usd,\n d.lineup_usd,d.machine_specific_usd,d.available_hours,v.gm_rank,v.verdict_chip,\n v.adjusted_rank,v.last_bank_name\n FROM workspace.royale.gold_machine_day d JOIN workspace.royale.gold_machine_verdict v USING (machine_id)', 'action_schedule': "\n      WITH tasks AS (\n        SELECT CASE action_type_id WHEN 'A-INSPECT' THEN 'Inspect M-1158' ELSE 'Move M-1184' END action,\n               CASE action_type_id WHEN 'A-INSPECT' THEN 'Wed' ELSE 'Thu' END eligible_weekday,\n               CAST(downtime_minutes / 60 AS INT) AS hours\n        FROM workspace.royale.gold_action_plan WHERE selected AND horizon_days=30\n        AND action_type_id IN ('A-INSPECT','A-MOVE-MACHINE')\n      ), windows AS (\n        SELECT t.action,t.hours,h.local_weekday,h.gaming_hour,\n               SUM(p.theo_per_available_machine_hour) AS lost_theo_usd\n        FROM tasks t CROSS JOIN workspace.royale.gold_forecast_tech_timing h\n        JOIN workspace.royale.gold_forecast_tech_timing p ON p.local_weekday=h.local_weekday\n          AND p.gaming_hour>=h.gaming_hour AND p.gaming_hour<h.gaming_hour+t.hours\n        WHERE (h.local_weekday=t.eligible_weekday AND h.gaming_hour+t.hours<=24)\n           OR (h.local_weekday='Sat' AND h.gaming_hour=13)\n        GROUP BY ALL HAVING COUNT(*)=t.hours\n      ), ranked AS (\n        SELECT *,ROW_NUMBER() OVER (PARTITION BY action,local_weekday ORDER BY lost_theo_usd,gaming_hour) AS preference\n        FROM windows\n      )\n      SELECT action,MAX(hours)*60 AS minutes,\n             MAX(IF(local_weekday<>'Sat',local_weekday,NULL)) AS weekday,\n             MAX(IF(local_weekday<>'Sat',gaming_hour,NULL)) AS start_hour,\n             MAX(IF(local_weekday<>'Sat',lost_theo_usd,NULL)) AS quiet_usd,\n             MAX(IF(local_weekday='Sat',lost_theo_usd,NULL)) AS saturday_usd\n      FROM ranked WHERE preference=1 GROUP BY action\n    ", 'adjusted': 'SELECT * FROM workspace.royale.gold_adjusted_bottom10', 'comparison': 'SELECT machine_id, theo_usd, house_win_usd, verdict_chip, gm_rank, adjusted_rank\n            FROM workspace.royale.gold_machine_verdict WHERE gm_rank<=10 OR adjusted_rank<=10', 'rank': 'SELECT * FROM workspace.royale.gold_bottom10_mean_reversion WHERE gm_rank<=10', 'floor': 'SELECT * FROM workspace.royale.gold_kpi_header', 'traffic': "SELECT *, CASE zone_id\n            WHEN 'Z-B40' THEN 'Back Forty' WHEN 'Z-BAR' THEN 'Bar Row' WHEN 'Z-ENT' THEN 'Main Entrance'\n            WHEN 'Z-GAR' THEN 'Garage Entrance' WHEN 'Z-HL' THEN 'High-Limit Room'\n            WHEN 'Z-HTL' THEN 'Hotel Corridor' WHEN 'Z-PIT' THEN 'Center Pit' END AS zone_name\n            FROM workspace.royale.gold_zone_gaming_hour", 'walkway': "SELECT *, CASE phase WHEN 'pre' THEN 'Before' WHEN 'closure' THEN 'During closure'\n            ELSE 'After' END AS period FROM workspace.royale.gold_walkway_did", 'demand': 'SELECT d.gaming_date,d.coin_in_usd,f.forecast_usd,f.split\n        FROM workspace.royale.gold_demand_context_day d\n        JOIN workspace.royale.gold_forecast_day f USING (gaming_date)', 'zones': 'SELECT * FROM workspace.royale.gold_zone_other_bridge', 'fault': "SELECT machine_id,gaming_date,gaming_hour,wait_seconds,work_seconds\n        FROM workspace.royale.gold_downtime_ticket WHERE event_type='fault_repair'", 'concentration': 'SELECT * FROM workspace.royale.gold_concentration', 'ladder': 'SELECT player_rank,cumulative_player_share,cumulative_theo_share,cumulative_coin_in_share\n            FROM workspace.royale.gold_lorenz WHERE PMOD(player_rank,400)=0 OR player_rank IN (1,1138,11389,113890)', 'segments': 'SELECT * FROM workspace.royale_export.gold_guest_group_day', 'outcomes': 'SELECT * FROM workspace.royale.gold_player_outcome_split', 'hist': "SELECT bin_id, CASE bin_id WHEN 0 THEN '0 No tracked gaming' WHEN 1 THEN '1 Below −$1,000'\n            WHEN 2 THEN '2 −$1,000 to −$100' WHEN 3 THEN '3 Loss under $100' WHEN 4 THEN '4 Exactly zero'\n            WHEN 5 THEN '5 Win up to $100' WHEN 6 THEN '6 $100 to $1,000' ELSE '7 Above $1,000' END AS band,\n            observations, player_net_usd FROM workspace.royale.gold_player_net_histogram WHERE period='Jan–Jun'", 'comps': 'SELECT *, valuation_date AS gaming_date FROM workspace.royale.gold_comp_week', 'control': 'SELECT * FROM workspace.royale.gold_comp_control_effect', 'points': 'SELECT * FROM workspace.royale.gold_points_liability_bridge', 'actions': 'SELECT * FROM workspace.royale.gold_action_plan WHERE horizon_days=30', 'annual': 'SELECT * FROM workspace.royale.gold_action_plan WHERE horizon_days=365', 'tech_sensitivity': "SELECT * FROM workspace.royale.gold_action_plan WHERE horizon_days=30 AND action_type_id IN ('A-TECH-SHIFT','A-PREVENTIVE')", 'cage': 'SELECT * FROM workspace.royale.gold_cage_slip', 'tech': 'SELECT * FROM workspace.royale.gold_tech_shift_economics WHERE horizon_days=30', 'forecast': 'SELECT * FROM workspace.royale.gold_forecast_day', 'scores': "SELECT model, scored_days, mae_usd, mape_pct FROM workspace.royale.gold_forecast_holdout_metrics\n             UNION ALL SELECT 'weekday_ridge_linear_trend', 61, 66519.66, 5.00", 'residual': 'SELECT * FROM workspace.royale.gold_forecast_weekday_residual', 'evidence': 'SELECT * FROM workspace.royale.gold_claims_evidence', 'lasting_gap': 'SELECT * FROM workspace.royale.gold_back_forty_lasting_gap', 'high_limit_test': 'SELECT * FROM workspace.royale.gold_high_limit_visit_test', 'high_limit_day': 'SELECT * FROM workspace.royale.gold_high_limit_visit_day', 'comp_control_week': 'SELECT * FROM workspace.royale.gold_comp_control_week', 'comp_control_pretrend': 'SELECT * FROM workspace.royale.gold_comp_control_pretrend', 'demand_bridge': 'SELECT * FROM workspace.royale_export.gold_demand_bridge_day', 'export_metadata': 'SELECT CAST(current_date() AS STRING) AS exported_on\n        FROM workspace.royale.gold_kpi_header LIMIT 1', 'downtime': 'SELECT gaming_date,gaming_hour,zone_id,manufacturer,\n        downtime_hours,lost_theo_usd FROM workspace.royale.gold_downtime_exposure_day_hour\n        WHERE downtime_hours > 0 OR lost_theo_usd <> 0', 'comp_days': 'SELECT k.gaming_date,k.comp_cost_usd,k.tracked_theo_usd,k.theo_usd,\n        COALESCE(r.points,0) AS points,COALESCE(r.face_usd,0) AS face_usd\n        FROM workspace.royale.gold_kpi_header k LEFT JOIN\n        (SELECT gaming_date,SUM(points) AS points,SUM(face_usd) AS face_usd\n         FROM workspace.royale.gold_comp_tier_day GROUP BY gaming_date) r USING (gaming_date)', 'timeline': "SELECT machine_id,gaming_date,\n SORT_ARRAY(COLLECT_LIST(NAMED_STRUCT('h', gaming_hour, 'utc', hour_start_utc,\n  'a', ROUND(available_hours,4), 'd', ROUND(downtime_hours,4)))) AS hours\n FROM workspace.royale.gold_machine_hour_leak\n WHERE downtime_hours > 0 OR ABS(available_hours - 1) > 0.00001\n GROUP BY machine_id,gaming_date", 'kpi_expected': "SELECT '2025-01-01' AS start, '2025-06-30' AS end,\n        CAST(ROUND(CAST(SUM(theo_usd) AS DOUBLE)/SUM(health_potential_usd),8) AS DECIMAL(22,8)) AS health,\n        CAST(ROUND(SUM(coin_in_usd),2) AS DECIMAL(22,2)) AS coin,\n        CAST(ROUND(CAST(SUM(house_win_usd) AS DOUBLE)/SUM(coin_in_usd),8) AS DECIMAL(22,8)) AS hold,\n        CAST(ROUND(CAST(SUM(theo_usd) AS DOUBLE)/SUM(coin_in_usd),8) AS DECIMAL(22,8)) AS theo_hold,\n        CAST(ROUND(SUM(luck_usd),2) AS DECIMAL(22,2)) AS luck,\n        CAST(ROUND(SUM(leak_usd),2) AS DECIMAL(22,2)) AS leak,\n        CAST(ROUND(CAST(SUM(comp_cost_usd) AS DOUBLE)/SUM(tracked_theo_usd),8) AS DECIMAL(22,8)) AS comp_kpi,\n        CAST(ROUND(SUM(luck_usd)/SQRT(SUM(luck_variance_usd2)),8) AS DECIMAL(22,8)) AS sigma_kpi,\n        (SELECT MAX(kept_usd) FROM workspace.royale.gold_cage_slip) AS cash_kept\n        FROM workspace.royale.gold_kpi_header WHERE gaming_date BETWEEN '2025-01-01' AND '2025-06-30' UNION ALL SELECT '2025-04-01' AS start, '2025-06-30' AS end,\n        CAST(ROUND(CAST(SUM(theo_usd) AS DOUBLE)/SUM(health_potential_usd),8) AS DECIMAL(22,8)) AS health,\n        CAST(ROUND(SUM(coin_in_usd),2) AS DECIMAL(22,2)) AS coin,\n        CAST(ROUND(CAST(SUM(house_win_usd) AS DOUBLE)/SUM(coin_in_usd),8) AS DECIMAL(22,8)) AS hold,\n        CAST(ROUND(CAST(SUM(theo_usd) AS DOUBLE)/SUM(coin_in_usd),8) AS DECIMAL(22,8)) AS theo_hold,\n        CAST(ROUND(SUM(luck_usd),2) AS DECIMAL(22,2)) AS luck,\n        CAST(ROUND(SUM(leak_usd),2) AS DECIMAL(22,2)) AS leak,\n        CAST(ROUND(CAST(SUM(comp_cost_usd) AS DOUBLE)/SUM(tracked_theo_usd),8) AS DECIMAL(22,8)) AS comp_kpi,\n        CAST(ROUND(SUM(luck_usd)/SQRT(SUM(luck_variance_usd2)),8) AS DECIMAL(22,8)) AS sigma_kpi,\n        (SELECT MAX(kept_usd) FROM workspace.royale.gold_cage_slip) AS cash_kept\n        FROM workspace.royale.gold_kpi_header WHERE gaming_date BETWEEN '2025-04-01' AND '2025-06-30' UNION ALL SELECT '2025-03-03' AS start, '2025-04-07' AS end,\n        CAST(ROUND(CAST(SUM(theo_usd) AS DOUBLE)/SUM(health_potential_usd),8) AS DECIMAL(22,8)) AS health,\n        CAST(ROUND(SUM(coin_in_usd),2) AS DECIMAL(22,2)) AS coin,\n        CAST(ROUND(CAST(SUM(house_win_usd) AS DOUBLE)/SUM(coin_in_usd),8) AS DECIMAL(22,8)) AS hold,\n        CAST(ROUND(CAST(SUM(theo_usd) AS DOUBLE)/SUM(coin_in_usd),8) AS DECIMAL(22,8)) AS theo_hold,\n        CAST(ROUND(SUM(luck_usd),2) AS DECIMAL(22,2)) AS luck,\n        CAST(ROUND(SUM(leak_usd),2) AS DECIMAL(22,2)) AS leak,\n        CAST(ROUND(CAST(SUM(comp_cost_usd) AS DOUBLE)/SUM(tracked_theo_usd),8) AS DECIMAL(22,8)) AS comp_kpi,\n        CAST(ROUND(SUM(luck_usd)/SQRT(SUM(luck_variance_usd2)),8) AS DECIMAL(22,8)) AS sigma_kpi,\n        (SELECT MAX(kept_usd) FROM workspace.royale.gold_cage_slip) AS cash_kept\n        FROM workspace.royale.gold_kpi_header WHERE gaming_date BETWEEN '2025-03-03' AND '2025-04-07'"}
import json
from pyspark.sql import functions as F

spark.sql("CREATE VOLUME IF NOT EXISTS workspace.royale.exports")
dbutils.widgets.text("export_id", "")
export_id = dbutils.widgets.get("export_id")
assert export_id.isdigit(), "Expected a numeric job run ID"
path = f"/Volumes/workspace/royale/exports/twin-{export_id}.json"
spark.conf.set("spark.sql.session.timeZone", "UTC")

with open(path, "w", encoding="utf-8") as output:
    output.write("{")
    for index, (name, query) in enumerate(QUERIES.items()):
        frame = spark.sql(query)
        encoded = frame.select(F.to_json(F.struct("*"), {"ignoreNullFields": "false"}).alias("line"))
        if index:
            output.write(",")
        output.write(json.dumps(name) + ':{"columns":' + json.dumps(frame.columns) + ',"rows":[')
        for row_index, row in enumerate(encoded.toLocalIterator()):
            if row_index:
                output.write(",")
            values = json.loads(row.line)
            output.write(json.dumps([values[c] for c in frame.columns], separators=(",", ":"), ensure_ascii=False))
        output.write("]}")
    output.write("}")
dbutils.jobs.taskValues.set(key="export_path", value=path)
